class Block4(nn.Module):
    def __init__(self, width=256, hidden=512):
        super().__init__()
        self.norm = nn.LayerNorm(width)
        self.fc1 = nn.Linear(width, hidden)
        self.fc2 = nn.Linear(hidden, width)

    def forward(self, x):
        n = self.norm(x)
        a = F.gelu(self.fc1(n))
        h = self.fc2(a)
        return x + h

